MATCH (p:Player)-[pf:PlaysFor]->(t:Team)
WHERE pf.tenure = 'latest'
  AND EXISTS { MATCH (p)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (t)-[:MentionedIn]->(:Document) }
  AND CAST(regexp_extract(p.draft_pick, '[0-9]+', 0) AS INT64) < 3
RETURN t.team_name AS col1, MIN(CAST(p.olympic_gold_medals AS INT64)) AS col2
